content.content:
  1→// Package compact converts full.jsonl transcripts into a normalized,
  2→// compact transcript.jsonl format. Only shared formatting is contained here.
  3→package compact
  4→
  5→import (
  6→	"bufio"
  7→	"bytes"
  8→	"encoding/json"
  9→	"fmt"
 10→	"io"
 11→	"strings"
 12→
 13→	"github.com/entireio/cli/cmd/entire/cli/textutil"
 14→	"github.com/entireio/cli/cmd/entire/cli/transcript"
 15→)
 16→
 17→// Options provides metadata fields written to every output line.
 18→type Options struct {
 19→	Agent      string // e.g. "claude-code"
 20→	CLIVersion string // e.g. "0.42.0"
 21→	StartLine  int    // checkpoint_transcript_start (0 = no truncation)
 22→}
 23→
 24→// compactMeta holds pre-computed JSON fragments for fields that are identical
 25→// on every output line, avoiding repeated marshaling.
 26→type compactMeta struct {
 27→	v          json.RawMessage
 28→	agent      json.RawMessage
 29→	cliVersion json.RawMessage
 30→}
 31→
 32→func newCompactMeta(opts Options) compactMeta {
 33→	return compactMeta{
 34→		v:          mustMarshal(1),
 35→		agent:      mustMarshal(opts.Agent),
 36→		cliVersion: mustMarshal(opts.CLIVersion),
 37→	}
 38→}
 39→
 40→// Compact converts a full.jsonl transcript into the condensed transcript.jsonl format.
 41→//
 42→// The output format puts version, agent, and cli_version on every line,
 43→// merges streaming assistant fragments with the same message ID, and inlines
 44→// tool results into the preceding assistant's tool_use blocks:
 45→//
 46→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
 47→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[{"type":"text","text":"..."},{"type":"tool_use","id":"...","name":"...","input":{...},"result":{"output":"...","status":"..."}}]}
 48→func Compact(content []byte, opts Options) ([]byte, error) {
 49→	truncated := transcript.SliceFromLine(content, opts.StartLine)
 50→	if truncated == nil {
 51→		truncated = []byte{}
 52→	}
 53→
 54→	if isOpenCodeFormat(truncated) {
 55→		return compactOpenCode(truncated, opts)
 56→	}
 57→
 58→	if isGeminiFormat(truncated) {
 59→		return compactGemini(truncated, opts)
 60→	}
 61→
 62→	if isCopilotFormat(truncated) {
 63→		return compactCopilot(truncated, opts)
 64→	}
 65→
 66→	if isDroidFormat(truncated) {
 67→		return compactDroid(truncated, opts)
 68→	}
 69→
 70→	return compactJSONL(truncated, opts)
 71→}
 72→
 73→// droppedTypes are JSONL entry types that carry no parser-relevant data.
 74→var droppedTypes = map[string]bool{
 75→	"progress":              true,
 76→	"file-history-snapshot": true,
 77→	"queue-operation":       true,
 78→	"system":                true,
 79→}
 80→
 81→// userAliases maps JSONL type/role values to the canonical "user" kind.
 82→// Covers Claude Code ("user", "human") and Cursor ("user" via "role" field).
 83→var userAliases = map[string]bool{
 84→	transcript.TypeUser: true,
 85→	"human":             true,
 86→}
 87→
 88→// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
 89→// JSONL transcript line. It checks the "type" field, then falls back to "role".
 90→// Returns "" for unrecognised or dropped entries.
 91→func normalizeKind(raw map[string]json.RawMessage) string {
 92→	kind := unquote(raw["type"])
 93→	if kind == "" {
 94→		kind = unquote(raw["role"])
 95→	}
 96→
 97→	if droppedTypes[kind] {
 98→		return ""
 99→	}
100→	if userAliases[kind] {
101→		return transcript.TypeUser
102→	}
103→	if kind == transcript.TypeAssistant {
104→		return transcript.TypeAssistant
105→	}
106→	return ""
107→}
108→
109→// linePreprocessor transforms a parsed JSONL line before conversion.
110→// Used by agent-specific converters to normalize their format (e.g., Droid
111→// envelope unwrapping) before the shared pipeline processes it.
112→type linePreprocessor func(map[string]json.RawMessage) map[string]json.RawMessage
113→
114→// compactJSONL converts JSONL transcripts (Claude Code, Cursor) into the
115→// compact format.
116→func compactJSONL(content []byte, opts Options) ([]byte, error) {
117→	return compactJSONLWith(content, opts, nil)
118→}
119→
120→// parsedEntry is an intermediate representation of a JSONL line used during
121→// the two-pass compact conversion.
122→type parsedEntry struct {
123→	kind        string // "user" or "assistant"
124→	ts          json.RawMessage
125→	id          string            // message ID (assistant only)
126→	content     json.RawMessage   // stripped assistant content array, or nil
127→	userText    string            // extracted user text
128→	toolResults []toolResultEntry // user tool_result entries
129→}
130→
131→// compactJSONLWith converts JSONL transcripts into the compact format.
132→// It uses a two-pass approach:
133→//  1. Parse all lines into intermediate entries
134→//  2. Merge streaming assistant fragments (same msg ID), inline tool results
135→//     from user lines into preceding assistant tool_use blocks, and drop
136→//     tool-result-only user lines.
137→func compactJSONLWith(content []byte, opts Options, preprocess linePreprocessor) ([]byte, error) {
138→	meta := newCompactMeta(opts)
139→
140→	// Pass 1: parse all lines into intermediate entries.
141→	entries, err := parseJSONLEntries(content, preprocess)
142→	if err != nil {
143→		return nil, err
144→	}
145→
146→	// Pass 2: merge and emit.
147→	var result []byte
148→	for i := 0; i < len(entries); i++ {
149→		e := entries[i]
150→
151→		switch e.kind {
152→		case transcript.TypeAssistant:
153→			// Merge consecutive assistant entries with the same message ID.
154→			merged := e
155→			for i+1 < len(entries) && entries[i+1].kind == transcript.TypeAssistant && entries[i+1].id == e.id {
156→				i++
157→				merged = mergeAssistantEntries(merged, entries[i])
158→			}
159→
160→			// Look ahead for user tool_result entries to inline.
161→			if i+1 < len(entries) && entries[i+1].kind == transcript.TypeUser && hasToolResults(entries[i+1]) {
162→				userEntry := entries[i+1]
163→				merged = inlineToolResults(merged, userEntry)
164→				i++ // consume the user tool_result entry
165→
166→				// If the consumed user entry also had text content, emit it
167→				// as a separate user line after the assistant.
168→				if userEntry.userText != "" {
169→					emitAssistant(&result, meta, merged)
170→					emitUser(&result, meta, userEntry)
171→					continue
172→				}
173→			}
174→
175→			if isEmptyContentArray(merged.content) {
176→				continue
177→			}
178→
179→			emitAssistant(&result, meta, merged)
180→
181→		case transcript.TypeUser:
182→			// User entries that are purely tool results were already consumed
183→			// by the assistant look-ahead above. If we reach one here it was
184→			// not preceded by an assistant with a matching tool_use, so emit
185→			// it only if it has text content.
186→			if hasToolResults(e) && e.userText == "" {
187→				continue
188→			}
189→			emitUser(&result, meta, e)
190→		}
191→	}
192→
193→	return result, nil
194→}
195→
196→func emitAssistant(result *[]byte, meta compactMeta, e parsedEntry) {
197→	b := marshalOrdered(
198→		"v", meta.v,
199→		"agent", meta.agent,
200→		"cli_version", meta.cliVersion,
201→		"type", mustMarshal(transcript.TypeAssistant),
202→		"ts", e.ts,
203→		"id", jsonStringOrNil(e.id),
204→		"content", e.content,
205→	)
206→	*result = append(*result, b...)
207→	*result = append(*result, '\n')
208→}
209→
210→func emitUser(result *[]byte, meta compactMeta, e parsedEntry) {
211→	b := marshalOrdered(
212→		"v", meta.v,
213→		"agent", meta.agent,
214→		"cli_version", meta.cliVersion,
215→		"type", mustMarshal(transcript.TypeUser),
216→		"ts", e.ts,
217→		"content", mustMarshal(e.userText),
218→	)
219→	*result = append(*result, b...)
220→	*result = append(*result, '\n')
221→}
222→
223→// parseJSONLEntries parses all JSONL lines into intermediate entries,
224→// filtering dropped types and malformed lines.
225→func parseJSONLEntries(content []byte, preprocess linePreprocessor) ([]parsedEntry, error) {
226→	reader := bufio.NewReader(bytes.NewReader(content))
227→	var entries []parsedEntry
228→
229→	for {
230→		lineBytes, err := reader.ReadBytes('\n')
231→		if err != nil && err != io.EOF {
232→			return nil, fmt.Errorf("reading JSONL line: %w", err)
233→		}
234→
235→		if len(bytes.TrimSpace(lineBytes)) > 0 {
236→			if e, ok := parseLine(lineBytes, preprocess); ok {
237→				entries = append(entries, e)
238→			}
239→		}
240→
241→		if err == io.EOF {
242→			break
243→		}
244→	}
245→
246→	return entries, nil
247→}
248→
249→// parseLine converts a single JSONL line into a parsedEntry.
250→// Returns ok=false for dropped/malformed lines.
251→func parseLine(lineBytes []byte, preprocess linePreprocessor) (parsedEntry, bool) {
252→	var raw map[string]json.RawMessage
253→	if err := json.Unmarshal(lineBytes, &raw); err != nil {
254→		return parsedEntry{}, false
255→	}
256→
257→	if preprocess != nil {
258→		raw = preprocess(raw)
259→	}
260→
261→	kind := normalizeKind(raw)
262→	if kind == "" {
263→		return parsedEntry{}, false
264→	}
265→
266→	e := parsedEntry{
267→		kind: kind,
268→		ts:   raw["timestamp"],
269→	}
270→
271→	msg := parseMessage(raw)
272→
273→	switch kind {
274→	case transcript.TypeAssistant:
275→		if msg != nil {
276→			e.id = unquote(msg["id"])
277→			if contentRaw, ok := msg["content"]; ok {
278→				e.content = stripAssistantContent(contentRaw)
279→			}
280→		}
281→
282→	case transcript.TypeUser:
283→		if msg != nil {
284→			if contentRaw, ok := msg["content"]; ok {
285→				text, toolResults := extractUserContent(contentRaw)
286→				e.userText = text
287→				e.toolResults = toolResults
288→			}
289→		}
290→		// Also check toolUseResult.stdout which may have the output.
291→		if turRaw, ok := raw["toolUseResult"]; ok {
292→			var tur map[string]json.RawMessage
293→			if json.Unmarshal(turRaw, &tur) == nil {
294→				if stdout := unquote(tur["stdout"]); stdout != "" {
295→					switch len(e.toolResults) {
296→					case 0:
297→						// Keep compatibility with transcripts that only include toolUseResult.
298→						e.toolResults = []toolResultEntry{{
299→							output: stdout,
300→						}}
301→					case 1:
302→						// toolUseResult is a single envelope for one tool call.
303→						e.toolResults[0].output = stdout
304→					}
305→				}
306→			}
307→		}
308→	}
309→
310→	return e, true
311→}
312→
313→// mergeAssistantEntries combines two assistant entries with the same message ID.
314→// Content arrays are concatenated; the later timestamp wins.
315→func mergeAssistantEntries(a, b parsedEntry) parsedEntry {
316→	merged := a
317→	merged.ts = b.ts
318→
319→	var aBlocks, bBlocks []json.RawMessage
320→	_ = json.Unmarshal(a.content, &aBlocks) //nolint:errcheck // best-effort merge
321→	_ = json.Unmarshal(b.content, &bBlocks) //nolint:errcheck // best-effort merge
322→	all := append(aBlocks, bBlocks...)      //nolint:gocritic // intentional append to new slice
323→	if data, err := json.Marshal(all); err == nil {
324→		merged.content = data
325→	}
326→
327→	return merged
328→}
329→
330→// inlineToolResults adds "result" fields to matching tool_use blocks in the
331→// assistant entry's content, using outputs from user tool_result entries.
332→func inlineToolResults(assistant, user parsedEntry) parsedEntry {
333→	var blocks []map[string]json.RawMessage
334→	if json.Unmarshal(assistant.content, &blocks) != nil || len(blocks) == 0 {
335→		return assistant
336→	}
337→
338→	for _, tr := range user.toolResults {
339→		// Find the tool_use block matching this tool_use_id.
340→		idx := -1
341→		for i := len(blocks) - 1; i >= 0; i-- {
342→			if unquote(blocks[i]["type"]) == transcript.ContentTypeToolUse {
343→				if tr.toolUseID == "" || unquote(blocks[i]["id"]) == tr.toolUseID {
344→					idx = i
345→					break
346→				}
347→			}
348→		}
349→		// No matching tool_use block: do not attach a result to unrelated content.
350→		if idx == -1 {
351→			continue
352→		}
353→
354→		status := "success"
355→		if tr.isError {
356→			status = "error"
357→		}
358→		resultObj := marshalOrdered(
359→			"output", mustMarshal(tr.output),
360→			"status", mustMarshal(status),
361→		)
362→		blocks[idx]["result"] = resultObj
363→	}
364→
365→	if data, err := json.Marshal(blocks); err == nil {
366→		assistant.content = data
367→	}
368→
369→	return assistant
370→}
371→
372→// jsonStringOrNil returns a JSON-encoded string, or nil if s is empty.
373→func jsonStringOrNil(s string) json.RawMessage {
374→	if s == "" {
375→		return nil
376→	}
377→	return mustMarshal(s)
378→}
379→
380→// isEmptyContentArray returns true if raw is a JSON empty array (`[]`).
381→func isEmptyContentArray(raw json.RawMessage) bool {
382→	var arr []json.RawMessage
383→	return json.Unmarshal(raw, &arr) == nil && len(arr) == 0
384→}
385→
386→func hasToolResults(e parsedEntry) bool {
387→	return len(e.toolResults) > 0
388→}
389→
390→type toolResultEntry struct {
391→	toolUseID string
392→	output    string
393→	isError   bool
394→}
395→
396→// parseMessage extracts and parses the "message" field from a JSONL transcript
397→// line. All JSONL agents nest content inside a "message" object.
398→func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
399→	msgRaw, ok := raw["message"]
400→	if !ok {
401→		return nil
402→	}
403→	var msg map[string]json.RawMessage
404→	if json.Unmarshal(msgRaw, &msg) == nil {
405→		return msg
406→	}
407→	return nil
408→}
409→
410→// extractUserContent separates user message content into text and tool_result entries.
411→// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
412→func extractUserContent(contentRaw json.RawMessage) (string, []toolResultEntry) {
413→	var str string
414→	if json.Unmarshal(contentRaw, &str) == nil {
415→		return textutil.StripIDEContextTags(str), nil
416→	}
417→
418→	var blocks []map[string]json.RawMessage
419→	if json.Unmarshal(contentRaw, &blocks) != nil {
420→		return "", nil
421→	}
422→
423→	var texts []string
424→	var toolResults []toolResultEntry
425→
426→	for _, block := range blocks {
427→		blockType := unquote(block["type"])
428→
429→		if blockType == "tool_result" {
430→			var isErr bool
431→			if raw, ok := block["is_error"]; ok {
432→				_ = json.Unmarshal(raw, &isErr) //nolint:errcheck // best-effort
433→			}
434→			toolResults = append(toolResults, toolResultEntry{
435→				toolUseID: unquote(block["tool_use_id"]),
436→				output:    unquote(block["content"]),
437→				isError:   isErr,
438→			})
439→			continue
440→		}
441→
442→		if blockType == transcript.ContentTypeText {
443→			stripped := textutil.StripIDEContextTags(unquote(block[transcript.ContentTypeText]))
444→			if stripped != "" {
445→				texts = append(texts, stripped)
446→			}
447→		}
448→	}
449→
450→	return strings.Join(texts, "\n\n"), toolResults
451→}
452→
453→func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
454→	var str string
455→	if json.Unmarshal(contentRaw, &str) == nil {
456→		return contentRaw
457→	}
458→
459→	var blocks []map[string]json.RawMessage
460→	if json.Unmarshal(contentRaw, &blocks) != nil {
461→		return contentRaw
462→	}
463→
464→	result := make([]map[string]json.RawMessage, 0, len(blocks))
465→	for _, block := range blocks {
466→		blockType := unquote(block["type"])
467→
468→		if blockType == "thinking" || blockType == "redacted_thinking" {
469→			continue
470→		}
471→
472→		if blockType == transcript.ContentTypeToolUse {
473→			stripped := make(map[string]json.RawMessage)
474→			copyField(stripped, block, "type")
475→			copyField(stripped, block, "id")
476→			copyField(stripped, block, "name")
477→			copyField(stripped, block, "input")
478→			result = append(result, stripped)
479→			continue
480→		}
481→
482→		result = append(result, block)
483→	}
484→
485→	b, err := json.Marshal(result)
486→	if err != nil {
487→		return contentRaw
488→	}
489→	return b
490→}
491→
492→// marshalOrdered produces a JSON object with keys in the given order.
493→// Pairs with nil values are omitted.
494→func marshalOrdered(pairs ...interface{}) []byte {
495→	var buf bytes.Buffer
496→	buf.WriteByte('{')
497→	first := true
498→	for i := 0; i < len(pairs)-1; i += 2 {
499→		key := pairs[i].(string)               //nolint:errcheck,forcetypeassert // contract: keys are always strings
500→		val, _ := pairs[i+1].(json.RawMessage) //nolint:errcheck // nil val is handled below
501→		if val == nil {
502→			continue
503→		}
504→		if !first {
505→			buf.WriteByte(',')
506→		}
507→		keyJSON, _ := json.Marshal(key) //nolint:errcheck,errchkjson // string keys never fail
508→		buf.Write(keyJSON)
509→		buf.WriteByte(':')
510→		buf.Write(val)
511→		first = false
512→	}
513→	buf.WriteByte('}')
514→	return buf.Bytes()
515→}
516→
517→// mustMarshal marshals v to JSON, panicking on error (which should never
518→// happen for the primitive types we pass).
519→func mustMarshal(v interface{}) json.RawMessage {
520→	b, _ := json.Marshal(v) //nolint:errcheck,errchkjson // only used with primitive types that never fail
521→	return b
522→}
523→
524→// copyField copies a single key from src to dst if it exists.
525→func copyField(dst, src map[string]json.RawMessage, key string) {
526→	if v, ok := src[key]; ok {
527→		dst[key] = v
528→	}
529→}
530→
531→// unquote JSON-decodes a raw message as a string. Returns "" on failure.
532→func unquote(raw json.RawMessage) string {
533→	var s string
534→	if json.Unmarshal(raw, &s) == nil {
535→		return s
536→	}
537→	return ""
538→}
539→

