434→// --- Helpers ---
435→
436→func assertFixtureTransform(t *testing.T, opts Options, inputPath, expectedPath string) {
437→	t.Helper()
438→
439→	input, err := os.ReadFile(inputPath)
440→	if err != nil {
441→		t.Fatalf("failed to read fixture %q: %v", inputPath, err)
442→	}
443→
444→	expected, err := os.ReadFile(expectedPath)
445→	if err != nil {
446→		t.Fatalf("failed to read expected output %q: %v", expectedPath, err)
447→	}
448→
449→	result, err := Compact(input, opts)
450→	if err != nil {
451→		t.Fatalf("unexpected error: %v", err)
452→	}
453→	assertJSONLines(t, result, nonEmptyLines(expected))
454→}
455→
456→func nonEmptyLines(data []byte) []string {
457→	var lines []string
458→	for _, line := range strings.Split(string(data), "\n") {
459→		if strings.TrimSpace(line) != "" {
460→			lines = append(lines, line)
461→		}
462→	}
463→	return lines
464→}
465→
466→// assertJSONLines compares actual output lines against expected JSON strings,
467→// using semantic JSON equality (order-independent for object keys).
468→func assertJSONLines(t *testing.T, actual []byte, expected []string) {
469→	t.Helper()
470→
471→	actualLines := nonEmptyLines(actual)
472→
473→	if len(expected) == 0 && len(actualLines) == 0 {
474→		return
475→	}
476→
477→	if len(actualLines) != len(expected) {
478→		t.Fatalf("line count mismatch: got %d, want %d\nactual:\n%s", len(actualLines), len(expected), string(actual))
479→	}
480→
481→	for i := range expected {
482→		var got, want interface{}
483→		if err := json.Unmarshal([]byte(actualLines[i]), &got); err != nil {
484→			t.Fatalf("line %d: failed to parse actual JSON: %v\nline: %s", i, err, actualLines[i])
485→		}
486→		if err := json.Unmarshal([]byte(expected[i]), &want); err != nil {
487→			t.Fatalf("line %d: failed to parse expected JSON: %v\nline: %s", i, err, expected[i])
488→		}
489→		if !reflect.DeepEqual(got, want) {
490→			prettyGot, _ := json.MarshalIndent(got, "", "  ")   //nolint:errcheck,errchkjson // test helper, marshal of interface{} is best-effort
491→			prettyWant, _ := json.MarshalIndent(want, "", "  ") //nolint:errcheck,errchkjson // test helper, marshal of interface{} is best-effort
492→			t.Errorf("line %d mismatch:\ngot:\n%s\nwant:\n%s", i, prettyGot, prettyWant)
493→		}
494→	}
495→}
